import{_ as o,a as t,o as a,a6 as r}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"Download a Purchased Downloadable Product","description":"","frontmatter":{"outline":false,"examples":[{"id":"download-purchased-product","title":"Download a Purchased File","description":"Stream the file behind a downloadable purchase. The response is binary, and each successful call consumes one of the customer's remaining downloads.","request":"GET /api/shop/customer-downloadable-products/403/download\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer 12|Iy8NExampleCustomerAccessToken\\n","response":"HTTP/1.1 200 OK\\nContent-Type: application/pdf\\nContent-Disposition: attachment; filename=user-guide.pdf\\n\\n[binary file content]\\n","commonErrors":[{"error":"401 Unauthorized — Unauthorized. Customer authentication required.","cause":"No customer Bearer token was sent","solution":"Log the customer in and send their token"},{"error":"404 Not Found — Downloadable product not found.","cause":"No such purchase, or it belongs to another customer","solution":"Use an id from Get Downloadable Products for this customer"},{"error":"403 Forbidden — Download is pending. Please wait for the order to be invoiced.","cause":"The order has not been invoiced, so the purchase is still pending","solution":"Nothing client-side — the store must invoice the order first"},{"error":"403 Forbidden — Download limit exceeded.","cause":"The downloads used have reached the quantity actually invoiced","solution":"Wait for the remaining quantity to be invoiced, or contact the store"},{"error":"403 Forbidden — No more downloads available.","cause":"Every purchased download has been used or canceled","solution":"The purchase is exhausted; its status is now expired"},{"error":"404 Not Found — File not found.","cause":"The stored file is missing on the server","solution":"Contact the store; the purchase record exists but its file does not"}]}]},"headers":[],"relativePath":"api/rest-api/shop/customer-downloadable-products/download-customer-downloadable-product.md","filePath":"api/rest-api/shop/customer-downloadable-products/download-customer-downloadable-product.md","lastUpdated":1786429091000}`),s={name:"api/rest-api/shop/customer-downloadable-products/download-customer-downloadable-product.md"};function d(n,e,i,l,c,h){return a(),t("div",null,e[0]||(e[0]=[r('<h1 id="download-a-purchased-downloadable-product" tabindex="-1">Download a Purchased Downloadable Product <a class="header-anchor" href="#download-a-purchased-downloadable-product" aria-label="Permalink to &quot;Download a Purchased Downloadable Product&quot;">​</a></h1><p>Stream the file a customer bought as a downloadable product.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/customer-downloadable-products/{id}/download</span></span></code></pre></div><p>The <code>{id}</code> is the purchase id from <a href="/api/rest-api/shop/customer-downloadable-products/get-customer-downloadable-products.html">Get Downloadable Products</a> — not a product or order id.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token of the customer who bought the product</td></tr></tbody></table><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>200 OK</code> with the raw file as the body. The content type follows the stored file, and <code>Content-Disposition</code> carries its original filename. Nothing about the response is JSON.</p><p>Both link types are served the same way: a <code>file</code> purchase streams from the store&#39;s private storage, and a <code>url</code> purchase is fetched by the store and passed through, so a client never receives the external address.</p><h2 id="each-download-is-counted" tabindex="-1">Each Download Is Counted <a class="header-anchor" href="#each-download-is-counted" aria-label="Permalink to &quot;Each Download Is Counted&quot;">​</a></h2><p>A successful call increments the used-download counter for the purchase, and the purchase flips to <code>expired</code> once nothing remains. Two separate limits apply, and each has its own error:</p><table tabindex="0"><thead><tr><th>Limit</th><th>When it trips</th></tr></thead><tbody><tr><td>Invoiced quantity</td><td>Downloads are released in step with what the store has invoiced. Using more than the invoiced share fails with <code>Download limit exceeded.</code> even though the purchase still shows remaining downloads.</td></tr><tr><td>Purchased quantity</td><td>Once used plus canceled downloads reach the bought quantity, the purchase is exhausted and fails with <code>No more downloads available.</code></td></tr></tbody></table><p>A purchase whose order has not been invoiced at all is <code>pending</code> and refuses with <code>Download is pending. Please wait for the order to be invoiced.</code></p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>&quot;Download&quot; button in the account area</strong> — call with the purchase id, then hand the returned blob to the user.</li><li><strong>Show the remaining count after a download</strong> — the counter changes server-side, so re-read <a href="/api/rest-api/shop/customer-downloadable-products/get-customer-downloadable-products.html">Get Downloadable Products</a> rather than decrementing locally.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Do not put this URL in an anchor tag</strong> — a browser navigation sends no <code>Authorization</code> or storefront-key header, and the request fails with <code>401</code>.</li><li><strong>Check the status code and content type before saving</strong> — every failure answers with JSON, so writing the body blind produces a file containing an error message.</li><li><strong>Do not retry a failed download automatically</strong> — a call that reaches the file consumes a download, and a blind retry loop can exhaust the customer&#39;s allowance.</li><li><strong>Read <code>remainingDownloads</code> before offering the button</strong> — a purchase already at zero fails with <code>403</code> rather than a friendly message.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/customer-downloadable-products/get-customer-downloadable-products.html">Get Downloadable Products</a> — the customer&#39;s purchased downloads</li><li><a href="/api/rest-api/shop/customer-downloadable-products/get-customer-downloadable-product.html">Get Downloadable Product</a> — one purchase with its remaining download count</li><li><a href="/api/rest-api/shop/customer-orders/get-customer-orders.html">Get Customer Orders</a> — the customer&#39;s order history</li></ul>',20)]))}const b=o(s,[["render",d]]);export{p as __pageData,b as default};
